/**
 * Generates src/calculators.ts (one typed function per calculator) and the
 * calculator reference in README.md from the definitions and labels.en.json.
 * Run: npm run generate. A test fails if the generated files are stale.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { calculate } from '../src/api'
import { examples, run, type CalcDef, type OutKind, type Unit } from '../src/engine'
import { CALCULATORS, GROUP_ORDER } from '../src/registry'

type Labels = {
  h1: string
  intro: string
  formula: string
  inputs: Record<string, string>
  outputs: Record<string, string>
  options?: Record<string, string>
  choices?: Record<string, string>
}

const ROOT = join(__dirname, '..')
const LABELS: Record<string, Labels> = JSON.parse(readFileSync(join(__dirname, 'labels.en.json'), 'utf8'))
const PAGE = 'https://analify-ai.scalyax.ai/tools'

export const fnName = (slug: string) =>
  slug.replace(/-calculator$/, '').replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase())
const typeName = (slug: string) => fnName(slug).replace(/^./, c => c.toUpperCase())

const IN_UNIT: Record<Unit, string> = {
  money: 'money, in normal currency units (45.5 = 45.50)',
  pct: 'percent (45 = 45%)',
  count: 'count',
  num: 'number',
  x: 'multiple (3 = 3×)',
  days: 'days',
  kg: 'kilograms',
  cm: 'centimetres',
  select: 'one of the listed options',
}
const OUT_UNIT: Record<OutKind, string> = {
  money: 'money, same currency as the inputs',
  pct: 'percent (45 = 45%)',
  x: 'multiple (3.25 = 3.25×)',
  count: 'count (unrounded; round for display)',
  num: 'number',
  days: 'days',
  months: 'months',
  kg: 'kilograms',
  choice: 'one of the listed choices',
  series: 'one money value per month',
}

const doc = (lines: string[], indent = '') =>
  `${indent}/**\n${lines.map(l => `${indent} *${l ? ` ${l}` : ''}`).join('\n')}\n${indent} */`

function exampleInputs(def: CalcDef): Record<string, number | string> {
  const ex = examples(def, 'en')
  return Object.fromEntries(def.inputs.map(i => [i.key, i.unit === 'select' ? ex[i.key] : Number(ex[i.key])]))
}

function block(def: CalcDef): string {
  const L = LABELS[def.slug]
  const T = typeName(def.slug)
  const outs = run(def, examples(def, 'en'))
  const inputType = def.inputs
    .map(i => {
      const type = i.unit === 'select' ? (i.options ?? []).map(o => `'${o}'`).join(' | ') : 'number'
      const opts = i.options ? ` Options: ${i.options.map(o => `'${o}' = ${L.options?.[o] ?? o}`).join(', ')}.` : ''
      return `${doc([`${L.inputs[i.key]}: ${IN_UNIT[i.unit]}.${opts}`], '  ')}\n  ${i.key}: ${type}`
    })
    .join('\n')
  const resultType = outs
    .map(o => {
      const choices = L.choices ? Object.keys(L.choices) : []
      const type = o.kind === 'choice' ? choices.map(c => `'${c}'`).join(' | ') : o.kind === 'series' ? 'number[]' : 'number'
      const legend = o.kind === 'choice' ? ` Choices: ${choices.map(c => `'${c}' = ${L.choices?.[c]}`).join(', ')}.` : ''
      return `${doc([`${L.outputs[o.key]}: ${OUT_UNIT[o.kind]}.${legend}`], '  ')}\n  ${o.key}: ${type} | null`
    })
    .join('\n')
  const fnDoc = doc([
    `${L.h1}. ${L.intro}`,
    '',
    '```text',
    ...L.formula.split('\n'),
    '```',
    '',
    `Try it free: ${PAGE}/${def.slug}`,
  ])
  return `export interface ${T}Input {\n${inputType}\n}\n\nexport interface ${T}Result {\n${resultType}\n}\n\n${fnDoc}\nexport function ${fnName(def.slug)}(input: ${T}Input): ${T}Result {\n  return calculate('${def.slug}', input as unknown as Record<string, InputValue>) as unknown as ${T}Result\n}\n`
}

export function generateSource(): string {
  return [
    '// Generated by scripts/generate.ts from the calculator definitions. Do not edit by hand.',
    "import { calculate, type InputValue } from './api'",
    '',
    ...CALCULATORS.map(block),
  ].join('\n')
}

const fmt = (v: unknown) =>
  v === null ? 'null' : Array.isArray(v) ? `[${v.slice(0, 3).join(', ')}, …]` : typeof v === 'string' ? `'${v}'` : String(Math.round(Number(v) * 100) / 100)

export function generateReference(): string {
  const groups: Record<string, string> = {
    profit: 'Profit and pricing',
    ads: 'Ads',
    delivery: 'Cash on delivery, shipping and returns',
    offers: 'Offers and order value',
    customers: 'Customers',
    conversion: 'Conversion and email',
    inventory: 'Inventory and shipping',
  }
  return GROUP_ORDER.map(g => {
    const defs = CALCULATORS.filter(c => c.group === g)
    return `### ${groups[g]}\n\n${defs
      .map(def => {
        const L = LABELS[def.slug]
        const input = exampleInputs(def)
        const result = calculate(def.slug, input)
        return `#### \`${fnName(def.slug)}()\` — ${L.h1}\n\n${L.intro}\n\n\`\`\`text\n${L.formula}\n\`\`\`\n\n\`\`\`ts\n${fnName(def.slug)}(${JSON.stringify(input, null, 0).replace(/"([a-zA-Z]+)":/g, '$1: ').replace(/,/g, ', ')})\n// → ${Object.entries(result)
          .map(([k, v]) => `${k}: ${fmt(v)}`)
          .join(', ')}\n\`\`\`\n\nFree online version: ${PAGE}/${def.slug}`
      })
      .join('\n\n')}`
  }).join('\n\n')
}

export const README_START = '<!-- calculators:start -->'
export const README_END = '<!-- calculators:end -->'

export function withReference(readme: string): string {
  const a = readme.indexOf(README_START)
  const b = readme.indexOf(README_END)
  if (a < 0 || b < 0) throw new Error('README is missing the calculator markers')
  return `${readme.slice(0, a + README_START.length)}\n\n${generateReference()}\n\n${readme.slice(b)}`
}

if (process.argv[1]?.endsWith('generate.ts')) {
  writeFileSync(join(ROOT, 'src', 'calculators.ts'), generateSource())
  const readmePath = join(ROOT, 'README.md')
  writeFileSync(readmePath, withReference(readFileSync(readmePath, 'utf8')))
  console.log(`Generated ${CALCULATORS.length} calculators.`)
}
